//go:build darwin || freebsd || openbsd || netbsd || dragonfly

package fswatch

import (
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"sync/atomic"

	"golang.org/x/sys/unix"
)

// ---------------------------------------------------------------------------
// kqueue.go: kqueue backend (macOS, FreeBSD, OpenBSD, NetBSD, DragonFlyBSD)
//
// Uses the kernel's kqueue/kevent mechanism to watch individual files and
// directories via EVFILT_VNODE. Unlike inotify, kqueue requires an open file
// descriptor per watched path, not just per directory. On macOS, O_EVTONLY
// opens files for event monitoring only; on other BSDs, O_RDONLY is used.
//
//	┌──────────────────────────────────────────────────────────────┐
//	│                       kqueueBackend                          │
//	│                                                              │
//	│  ┌───────────┐       kevent(2)        ┌──────────────────┐   │
//	│  │ pipe[0]   ├───────────────────────►│                  │   │
//	│  │ (wakeup)  │                        │  start()         │   │
//	│  └───────────┘                        │  goroutine       │   │
//	│  ┌───────────┐      EVFILT_VNODE      │  (event loop)    │   │
//	│  │ kqueue    ├───────────────────────►│                  │   │
//	│  │ fd        │                        └────────┬─────────┘   │
//	│  └───────────┘                                 │             │
//	│                                                ▼             │
//	│             ┌──────────────────────────────────────────────┐ │
//	│             │  fdToEntry:  map[fd]   → *dirEntry           │ │
//	│             │  subsByPath: map[path] → []*kqueueSub        │ │
//	│             │                                              │ │
//	│             │  Each dirEntry.state stores the open fd      │ │
//	│             └──────────────────────────────────────────────┘ │
//	└──────────────────────────────────────────────────────────────┘
//
// Goroutines and threading:
//   - One long-lived goroutine (start), launched by watcherBase.run(). It
//     owns the kevent(2) loop and runs for the process lifetime. All event
//     dispatch (compareDir, handleFileEvent) executes on this goroutine.
//     compareDir and handleFileEvent acquire b.mu for watch/fd lookups.
//   - subscribe/closeWatch run on the caller's goroutine under
//     watcherBase.mu. watchPath acquires b.mu to register fd mappings.
//
// Callback delivery:
//   dirWatch.notify() posts to the shared process-wide debouncer. After a
//   coalescing window (50 ms min / 500 ms max), the debouncer invokes all
//   registered WatchCallbacks on its own dedicated goroutine; never on
//   the caller's goroutine or the event-loop goroutine.
//
// WatchDirectory flow:
//  1. Walk the target directory, building a path→dirEntry map (caller goroutine).
//  2. For every entry (file or directory), open an fd and register it with
//     kqueue for EVFILT_VNODE events (NOTE_DELETE, NOTE_WRITE, NOTE_EXTEND,
//     NOTE_ATTRIB, NOTE_RENAME, NOTE_REVOKE). Store the fd↔dirEntry mapping.
//
// Event dispatch (on the start goroutine):
//   - NOTE_WRITE on a directory → compareDir: re-read the directory from
//     disk, diff against the in-memory tree, emit update events for new
//     entries (opening + watching them) and delete events for removed ones
//     (closing their fds).
//   - NOTE_DELETE / NOTE_RENAME / NOTE_REVOKE → close the stale fd. For a
//     pure NOTE_DELETE on a file, tryRewatchLocked checks whether the path
//     was immediately recreated (atomic-save pattern) and emits update
//     instead of delete if so. Otherwise emit delete and remove from the
//     tree. Directories skip tryRewatchLocked to avoid spurious updates
//     during RemoveAll races.
//   - NOTE_WRITE / NOTE_ATTRIB / NOTE_EXTEND on a file → emit update.
//   After processing all returned kevents, call dirWatch.notify() on each
//   touched dirWatch to trigger the debouncer.
//
// Shutdown:
//   Write a byte to pipe[1] → kevent sees the pipe fd → loop exits →
//   close all tracked fds, the kqueue fd, and the pipe.
// ---------------------------------------------------------------------------

// openForEvents opens a path for kqueue event monitoring. On darwin, O_EVTONLY
// opens the file for event notification without granting read access. On other
// BSDs, falls back to O_RDONLY.
func openForEvents(path string) (int, error) {
	flags := unix.O_RDONLY
	if runtime.GOOS == "darwin" {
		flags = 0x8000 // O_EVTONLY, darwin-only
	}
	return unix.Open(path, flags, 0)
}

// dirEntry tracks a watched path for kqueue's fd↔path mapping.
type dirEntry struct {
	path      string
	watchPath string
	isDir     bool
	state     any // stores the open fd
}

// kqueueSubscription.
type kqueueSubscription struct {
	dirWatch *dirWatch
	path     string
	entries  map[string]*dirEntry
	fd       int
}

// kqueueBackend. It embeds treeReaderBackend (via Go
// composition) just like the inheritance hierarchy.
type kqueueBackend struct {
	watcherBase

	mu sync.Mutex // local lock for kqueue-specific maps
	kq int
	// pipeFDs[0] is read in the Start goroutine only. pipeFDs[1] is written
	// by Shutdown (any goroutine) to wake the loop, so it lives in
	// pipeWriteFD as an atomic with a sentinel of -1 once closed.
	pipeFDs     [2]int
	pipeWriteFD atomic.Int32
	subsByPath  map[string][]*kqueueSubscription // multimap<path, sub>
	fdToEntry   map[int]*dirEntry
	endedSignal chan struct{}

	// Persistent buffer reused across event batches. Only accessed
	// from the start goroutine, so no synchronization needed.
	watchersTouched map[*dirWatch]struct{}
}

func init() {
	kqueueWatcher.factory = func() watcherImpl { return newKqueueBackend() }
}

func newKqueueBackend() *kqueueBackend {
	b := &kqueueBackend{
		kq:              -1,
		pipeFDs:         [2]int{-1, -1},
		subsByPath:      map[string][]*kqueueSubscription{},
		fdToEntry:       map[int]*dirEntry{},
		endedSignal:     make(chan struct{}),
		watchersTouched: make(map[*dirWatch]struct{}),
	}
	b.pipeWriteFD.Store(-1)
	b.watcherBase.init(b)
	return b
}

func (b *kqueueBackend) start() error {
	kq, err := unix.Kqueue()
	if err != nil {
		return fmt.Errorf("unable to open kqueue: %w", err)
	}
	b.kq = kq
	defer func() {
		b.closeSubscriptions()
		b.closeFDs()
		close(b.endedSignal)
	}()

	if err := unix.Pipe(b.pipeFDs[:]); err != nil {
		return fmt.Errorf("unable to open pipe: %w", err)
	}
	b.pipeWriteFD.Store(int32(b.pipeFDs[1]))

	// WatchDirectory kqueue to the read side of the pipe so we can break the
	// loop on shutdown. SetKevent handles the per-arch Ident type
	// (uint64 on 64-bit, uint32 on 386/arm).
	var pipeEv unix.Kevent_t
	unix.SetKevent(&pipeEv, b.pipeFDs[0], unix.EVFILT_READ, unix.EV_ADD|unix.EV_CLEAR)
	if _, err := unix.Kevent(kq, []unix.Kevent_t{pipeEv}, nil, nil); err != nil {
		return fmt.Errorf("unable to watch pipe: %w", err)
	}

	b.notifyStarted()

	events := make([]unix.Kevent_t, 128)
	for {
		n, err := unix.Kevent(kq, nil, events, nil)
		if err != nil {
			if err == unix.EINTR {
				continue
			}
			return fmt.Errorf("kevent error: %w", err)
		}

		watchersTouched := b.watchersTouched
		stop := false
		for i := range n {
			fflags := events[i].Fflags
			flags := events[i].Flags
			fd := int(events[i].Ident)
			if fd == b.pipeFDs[0] {
				stop = true
				break
			}

			// EV_ERROR indicates kevent couldn't apply a changelist
			// entry or that the kernel rejected the registration.
			// Data carries the errno. Skip dispatching as a normal
			// event since fflags are not meaningful in this case.
			if flags&unix.EV_ERROR != 0 {
				continue
			}

			b.mu.Lock()
			entry, ok := b.fdToEntry[fd]
			b.mu.Unlock()
			if !ok || entry == nil {
				continue
			}

			if fflags&unix.NOTE_WRITE != 0 && entry.isDir {
				b.compareDir(fd, entry.path, watchersTouched)
				// NOTE_WRITE on a dir already ran compareDir above.
				// On DragonFlyBSD, rename-over coalesces NOTE_DELETE
				// with NOTE_WRITE on the parent directory (rather than
				// firing NOTE_DELETE on the replaced file's fd).
				// Skip handleFileEvent so we don't misinterpret the
				// coalesced NOTE_DELETE as the directory itself being
				// removed.
				fflags &^= unix.NOTE_DELETE
			}
			if fflags&^unix.NOTE_WRITE != 0 || !entry.isDir {
				b.handleFileEvent(fflags, entry, watchersTouched)
			}
		}

		for w := range watchersTouched {
			w.notify()
		}
		clear(watchersTouched)
		if stop {
			break
		}
	}

	return nil
}

func (b *kqueueBackend) closeFDs() {
	if b.pipeFDs[0] >= 0 {
		_ = unix.Close(b.pipeFDs[0])
		b.pipeFDs[0] = -1
	}
	if fd := b.pipeWriteFD.Swap(-1); fd >= 0 {
		_ = unix.Close(int(fd))
	}
	b.pipeFDs[1] = -1
	if b.kq >= 0 {
		_ = unix.Close(b.kq)
		b.kq = -1
	}
}

func (b *kqueueBackend) closeSubscriptions() {
	b.mu.Lock()
	seenFDs := map[int]struct{}{}
	for _, list := range b.subsByPath {
		for _, sub := range list {
			if sub.fd < 0 {
				continue
			}
			if _, ok := seenFDs[sub.fd]; ok {
				continue
			}
			seenFDs[sub.fd] = struct{}{}
			_ = unix.Close(sub.fd)
		}
	}
	b.subsByPath = map[string][]*kqueueSubscription{}
	b.fdToEntry = map[int]*dirEntry{}
	b.mu.Unlock()
}

func (b *kqueueBackend) shutdown() {
	fd := b.pipeWriteFD.Load()
	if fd < 0 {
		return
	}
	_, _ = unix.Write(int(fd), []byte{'X'})
	<-b.endedSignal
}

func (b *kqueueBackend) handleFileEvent(fflags uint32, entry *dirEntry, touched map[*dirWatch]struct{}) {
	b.mu.Lock()
	defer b.mu.Unlock()
	subs := b.findSubscriptionsLocked(entry.path)

	if fflags&(unix.NOTE_DELETE|unix.NOTE_RENAME|unix.NOTE_REVOKE) != 0 {
		// Close the stale fd; the watched inode is gone.
		if oldFD, ok := entry.state.(int); ok {
			unix.Close(oldFD)
			delete(b.fdToEntry, oldFD)
			entry.state = nil
		}

		recreated := false
		if fflags&unix.NOTE_DELETE != 0 && fflags&(unix.NOTE_RENAME|unix.NOTE_REVOKE) == 0 && !entry.isDir {
			recreated = b.tryRewatchLocked(entry)
		}

		for _, sub := range subs {
			touched[sub.dirWatch] = struct{}{}
			if recreated {
				sub.dirWatch.events.update(sub.path)
			} else {
				sub.dirWatch.events.remove(sub.path)
				// If we lost a directory, walk the entries map and
				// close every fd we had open for descendants. Some
				// kernels (OpenBSD in particular) deliver only the
				// parent's NOTE_DELETE/NOTE_RENAME and never fire
				// NOTE_DELETE on the children; without this cleanup,
				// modifying a file inside the moved tree later
				// surfaces an event against the descendant's stale
				// (pre-rename) path. We also emit a delete for each
				// descendant we close, so callers don't miss those
				// removals if the kernel didn't fire per-child events.
				// (When the kernel does fire them, our follow-up
				// handleFileEvent finds the fd already gone and is a
				// no-op, so events.create's coalescing handles dups.)
				if entry.isDir {
					b.closeDescendantFDsLocked(sub.dirWatch, sub.entries, sub.path)
				}
				removeEntryAndDescendants(sub.entries, sub.path)
				// Root-of-watch deletion: no more events can fire
				// for this dirWatch. Tell the caller.
				if sub.path == sub.dirWatch.dir {
					sub.dirWatch.events.setError(fmt.Errorf("%w: watched directory removed", ErrWatchTerminated))
				}
			}
		}
		if !recreated {
			delete(b.subsByPath, entry.path)
		}
		return
	}

	for _, sub := range subs {
		touched[sub.dirWatch] = struct{}{}
		if fflags&(unix.NOTE_WRITE|unix.NOTE_ATTRIB|unix.NOTE_EXTEND) != 0 {
			sub.dirWatch.events.update(sub.path)
		}
	}
}

// closeDescendantFDsLocked closes every fd attached to an entry whose
// path lives strictly under root, removing the kevent registration and
// the corresponding b.subsByPath / b.fdToEntry bookkeeping, and emits a
// delete event for each. Used when a directory's parent is lost
// (deleted, renamed away) and the kernel didn't propagate the loss to
// children. eventList coalesces against any per-child NOTE_DELETE that
// arrives later.
func (b *kqueueBackend) closeDescendantFDsLocked(w *dirWatch, entries map[string]*dirEntry, root string) {
	prefix := root + string(filepath.Separator)
	for path, e := range entries {
		if !strings.HasPrefix(path, prefix) {
			continue
		}
		if fd, ok := e.state.(int); ok {
			unix.Close(fd)
			delete(b.fdToEntry, fd)
			e.state = nil
		}
		delete(b.subsByPath, path)
		w.events.remove(path)
	}
}

// tryRewatchLocked checks whether a deleted path was immediately recreated
// with the same type. If so, it opens a new fd, registers a kqueue watch,
// and returns true. The caller should emit update instead of delete.
func (b *kqueueBackend) tryRewatchLocked(entry *dirEntry) bool {
	var st unix.Stat_t
	if unix.Lstat(entry.watchPath, &st) != nil {
		return false
	}

	// Only fast-path when the recreated path has the same type;
	// a file→dir change needs a full tree rebuild via compareDir.
	newIsDir := st.Mode&unix.S_IFMT == unix.S_IFDIR
	if newIsDir != entry.isDir {
		return false
	}

	fd, err := openForEvents(entry.watchPath)
	if err != nil {
		return false
	}

	var ev unix.Kevent_t
	unix.SetKevent(&ev, fd, unix.EVFILT_VNODE, unix.EV_ADD|unix.EV_CLEAR|unix.EV_ENABLE)
	ev.Fflags = unix.NOTE_DELETE | unix.NOTE_WRITE | unix.NOTE_EXTEND |
		unix.NOTE_ATTRIB | unix.NOTE_RENAME | unix.NOTE_REVOKE
	if _, err := unix.Kevent(b.kq, []unix.Kevent_t{ev}, nil, nil); err != nil {
		unix.Close(fd)
		return false
	}

	entry.state = fd

	b.fdToEntry[fd] = entry
	return true
}

func (b *kqueueBackend) closeEntryLocked(entry *dirEntry) {
	if fd, ok := entry.state.(int); ok {
		unix.Close(fd)
		delete(b.fdToEntry, fd)
		entry.state = nil
	}
}

func (b *kqueueBackend) removeSubsForEntriesLocked(path string, entriesPtr *map[string]*dirEntry) {
	list := b.subsByPath[path]
	kept := list[:0]
	for _, sub := range list {
		if &sub.entries == entriesPtr {
			continue
		}
		kept = append(kept, sub)
	}
	if len(kept) == 0 {
		delete(b.subsByPath, path)
	} else {
		b.subsByPath[path] = kept
	}
}

func (b *kqueueBackend) removeEntryAndDescendantsLocked(entriesPtr *map[string]*dirEntry, path string, includeRoot bool) {
	entries := *entriesPtr
	for descendant, e := range entries {
		if descendant == path {
			if !includeRoot {
				continue
			}
		} else if !(len(descendant) > len(path) && descendant[len(path)] == filepath.Separator && descendant[:len(path)] == path) {
			continue
		}
		b.closeEntryLocked(e)
		b.removeSubsForEntriesLocked(descendant, entriesPtr)
		delete(entries, descendant)
	}
}

func (b *kqueueBackend) findSubscriptionsLocked(path string) []*kqueueSubscription {
	subs := b.subsByPath[path]
	out := make([]*kqueueSubscription, len(subs))
	copy(out, subs)
	return out
}

// subscribe mirrors `kqueueBackend::subscribe`. Called under watcherBase.mu
// via watchAdd.
func (b *kqueueBackend) subscribe(w *dirWatch) error {
	// Build the entries map without registering any watches or
	// subscriptions. This avoids a data race: registering a subscription
	// publishes the entries map to the event loop (via subsByPath),
	// which could read it via compareDir while we're still populating it.
	entries := map[string]*dirEntry{}
	if err := walkDir(w.physicalDir, w.recursive, func(watchPath string, isDir bool) error {
		path := w.displayPath(watchPath)
		entries[path] = &dirEntry{path: path, watchPath: watchPath, isDir: isDir}
		return nil
	}); err != nil {
		return err
	}

	// Open fds, register kevents, and publish subscriptions under b.mu.
	// Holding the lock for the entire block ensures that the event loop
	// cannot see a partially-built entries map, and that fds are always
	// tracked in fdToEntry (no leak on early return).
	b.mu.Lock()
	defer b.mu.Unlock()

	for path, entry := range entries {
		fd, err := openForEvents(entry.watchPath)
		if err != nil {
			if path == w.dir {
				b.cleanupEntriesLocked(entries)
				return &dirWatchError{
					err:      fmt.Errorf("error watching %s: %w", w.dir, err),
					dirWatch: w,
				}
			}
			delete(entries, path)
			continue
		}
		var ev unix.Kevent_t
		unix.SetKevent(&ev, fd, unix.EVFILT_VNODE, unix.EV_ADD|unix.EV_CLEAR|unix.EV_ENABLE)
		ev.Fflags = unix.NOTE_DELETE | unix.NOTE_WRITE | unix.NOTE_EXTEND |
			unix.NOTE_ATTRIB | unix.NOTE_RENAME | unix.NOTE_REVOKE
		if _, err := unix.Kevent(b.kq, []unix.Kevent_t{ev}, nil, nil); err != nil {
			unix.Close(fd)
			if path == w.dir {
				b.cleanupEntriesLocked(entries)
				return &dirWatchError{
					err:      fmt.Errorf("error watching %s: %w", w.dir, err),
					dirWatch: w,
				}
			}
			delete(entries, path)
			continue
		}
		entry.state = fd
		b.fdToEntry[fd] = entry
	}

	for path, entry := range entries {
		fd := entry.state.(int)
		sub := &kqueueSubscription{dirWatch: w, path: path, entries: entries, fd: fd}
		b.subsByPath[path] = append(b.subsByPath[path], sub)
	}
	return nil
}

// cleanupEntriesLocked closes fds for all entries that have been opened.
// Called on subscribe failure to avoid fd leaks. Must be called under b.mu.
func (b *kqueueBackend) cleanupEntriesLocked(entries map[string]*dirEntry) {
	for _, e := range entries {
		if fd, ok := e.state.(int); ok {
			unix.Close(fd)
			delete(b.fdToEntry, fd)
			e.state = nil
		}
	}
}

// watchPath corresponds to `kqueueBackend::watchDir`.
func (b *kqueueBackend) watchPath(w *dirWatch, path string, entries map[string]*dirEntry) bool {
	entry := entries[path]
	if entry == nil {
		return false
	}
	b.mu.Lock()
	defer b.mu.Unlock()

	sub := &kqueueSubscription{dirWatch: w, path: path, entries: entries}
	if entry.state == nil {
		fd, err := openForEvents(entry.watchPath)
		if err != nil {
			return false
		}
		var ev unix.Kevent_t
		unix.SetKevent(&ev, fd, unix.EVFILT_VNODE, unix.EV_ADD|unix.EV_CLEAR|unix.EV_ENABLE)
		ev.Fflags = unix.NOTE_DELETE | unix.NOTE_WRITE | unix.NOTE_EXTEND |
			unix.NOTE_ATTRIB | unix.NOTE_RENAME | unix.NOTE_REVOKE
		if _, err := unix.Kevent(b.kq, []unix.Kevent_t{ev}, nil, nil); err != nil {
			unix.Close(fd)
			return false
		}
		entry.state = fd
		b.fdToEntry[fd] = entry
	}
	sub.fd = entry.state.(int)
	b.subsByPath[path] = append(b.subsByPath[path], sub)
	return true
}

// compareDir mirrors `kqueueBackend::compareDir`. Triggered when a watched
// directory has NOTE_WRITE: list the dir, diff against the tree, emit
// create/remove events.
func (b *kqueueBackend) compareDir(_ int, path string, touched map[*dirWatch]struct{}) bool {
	b.mu.Lock()
	subs := b.findSubscriptionsLocked(path)
	b.mu.Unlock()

	// For non-recursive subscriptions, only compareDir on the root dir.
	// NOTE_WRITE on a child dir means something changed inside it, but
	// non-recursive mode shouldn't report those changes. Emit an update
	// for the child dir itself (its metadata changed) and return.
	filteredSubs := subs[:0:0]
	for _, s := range subs {
		if !s.dirWatch.recursive && path != s.dirWatch.dir {
			s.dirWatch.events.update(path)
			touched[s.dirWatch] = struct{}{}
		} else {
			filteredSubs = append(filteredSubs, s)
		}
	}
	if len(filteredSubs) == 0 {
		return true
	}
	subs = filteredSubs

	dirStart := path + string(filepath.Separator)
	type diskSnapshot struct {
		entries             []os.DirEntry
		currentDisplayPaths map[string]struct{}
	}
	snapshots := map[string]diskSnapshot{}

	// Each subscription has its own entries map (built in subscribe).
	// Multiple subs at the same path arise from multiple dirWatches
	// covering overlapping subtrees; their maps are always distinct, so
	// we iterate subs directly rather than trying to dedup by map identity.
	for _, sub := range subs {
		baseEntry := sub.entries[path]
		if baseEntry == nil {
			continue
		}
		watchPath := baseEntry.watchPath
		watchDirStart := watchPath + string(filepath.Separator)

		snapshot, ok := snapshots[watchPath]
		if !ok {
			diskEntries, err := readEntries(watchPath)
			if err != nil {
				continue
			}
			snapshot.entries = diskEntries
			snapshot.currentDisplayPaths = make(map[string]struct{}, len(diskEntries))
			for _, ent := range diskEntries {
				snapshot.currentDisplayPaths[dirStart+ent.Name()] = struct{}{}
			}
			snapshots[watchPath] = snapshot
		}

		entries := sub.entries
		for _, ent := range snapshot.entries {
			fullPath := dirStart + ent.Name()
			fullWatchPath := watchDirStart + ent.Name()

			existing := entries[fullPath]
			if existing != nil {
				if existing.state != nil {
					// Check if the fd still refers to the same inode as
					// the path on disk. On DragonFlyBSD, rename-over
					// doesn't fire NOTE_DELETE on the replaced file's fd,
					// leaving a stale entry whose fd points to the old
					// (now unlinked) inode.
					if fd, ok := existing.state.(int); ok {
						var fdSt, pathSt unix.Stat_t
						if unix.Fstat(fd, &fdSt) == nil && unix.Lstat(fullWatchPath, &pathSt) == nil {
							if fdSt.Dev != pathSt.Dev || fdSt.Ino != pathSt.Ino {
								// Inode changed: path was replaced.
								b.mu.Lock()
								b.closeEntryLocked(existing)
								b.removeSubsForEntriesLocked(fullPath, &sub.entries)
								if existing.isDir {
									b.removeEntryAndDescendantsLocked(&sub.entries, fullPath, false)
								}
								existing.isDir = ent.IsDir()
								b.mu.Unlock()
							}
						}
					}
				}
				if existing.state != nil {
					continue
				}
				// Entry exists but fd is stale: the file was replaced.
				// Re-watch it and emit an update.
				if !b.watchPath(sub.dirWatch, fullPath, entries) {
					continue
				}
				sub.dirWatch.events.update(fullPath)
				touched[sub.dirWatch] = struct{}{}
				if ent.IsDir() && sub.dirWatch.recursive {
					_ = walkDir(fullWatchPath, true, func(p string, pIsDir bool) error {
						if p == fullWatchPath {
							return nil
						}
						displayPath := sub.dirWatch.displayPath(p)
						e := &dirEntry{path: displayPath, watchPath: p, isDir: pIsDir}
						entries[displayPath] = e
						sub.dirWatch.events.create(displayPath)
						b.watchPath(sub.dirWatch, displayPath, entries)
						return nil
					})
				}
				continue
			}
			e := &dirEntry{path: fullPath, watchPath: fullWatchPath, isDir: ent.IsDir()}
			entries[fullPath] = e
			if !b.watchPath(sub.dirWatch, fullPath, entries) {
				delete(entries, fullPath)
				continue
			}
			sub.dirWatch.events.create(fullPath)
			touched[sub.dirWatch] = struct{}{}

			// For recursive subscriptions, walk into the new directory
			// to catch pre-populated subdirectories (e.g. a directory
			// tree moved into the watched area).
			if ent.IsDir() && sub.dirWatch.recursive {
				_ = walkDir(fullWatchPath, true, func(p string, pIsDir bool) error {
					if p == fullWatchPath {
						return nil // already handled above
					}
					displayPath := sub.dirWatch.displayPath(p)
					entry := &dirEntry{path: displayPath, watchPath: p, isDir: pIsDir}
					entries[displayPath] = entry
					sub.dirWatch.events.create(displayPath)
					b.watchPath(sub.dirWatch, displayPath, entries)
					return nil
				})
			}
		}

		// Detect removals: entries directly under dirStart that no longer
		// exist on disk.
		var toRemove []string
		for p := range entries {
			if !strings.HasPrefix(p, dirStart) {
				continue
			}
			rest := p[len(dirStart):]
			if strings.Contains(rest, string(filepath.Separator)) {
				continue
			}
			if _, ok := snapshot.currentDisplayPaths[p]; ok {
				continue
			}
			toRemove = append(toRemove, p)
		}
		for _, p := range toRemove {
			sub.dirWatch.events.remove(p)
			touched[sub.dirWatch] = struct{}{}
			b.mu.Lock()
			for descendant, e := range entries {
				if descendant != p && !(len(descendant) > len(p) && descendant[len(p)] == filepath.Separator && descendant[:len(p)] == p) {
					continue
				}
				if fd, ok := e.state.(int); ok {
					unix.Close(fd)
					delete(b.fdToEntry, fd)
				}
				delete(b.subsByPath, descendant)
			}
			b.mu.Unlock()
			removeEntryAndDescendants(entries, p)
		}
	}
	return true
}

// readEntries lists directory entries (excluding "." and "..") at path.
func readEntries(path string) ([]os.DirEntry, error) {
	return os.ReadDir(path)
}

// closeWatch mirrors `kqueueBackend::closeWatch`.
func (b *kqueueBackend) closeWatch(w *dirWatch) error {
	b.mu.Lock()
	defer b.mu.Unlock()
	for path, list := range b.subsByPath {
		kept := list[:0]
		removedAny := false
		for _, s := range list {
			if s.dirWatch == w {
				removedAny = true
				continue
			}
			kept = append(kept, s)
		}
		if !removedAny {
			continue
		}
		if len(kept) == 0 {
			// Closing the file descriptor automatically unwatches it in kqueue.
			fd := list[0].fd
			unix.Close(fd)
			delete(b.fdToEntry, fd)
			delete(b.subsByPath, path)
		} else {
			b.subsByPath[path] = kept
		}
	}
	return nil
}

// removeEntryAndDescendants removes path and all paths prefixed with
// path + separator from the entries map.
func removeEntryAndDescendants(entries map[string]*dirEntry, path string) {
	delete(entries, path)
	for k := range entries {
		if len(k) > len(path) && k[len(path)] == filepath.Separator && k[:len(path)] == path {
			delete(entries, k)
		}
	}
}

tsc/internal/fswatch/watcher_test.go.text:
// Watcher tests: CRUD events for files, directories, sub-entries, and
// symlinks; event coalescing; multiple subscriptions; error handling;
// watch lifecycle; public API validation; and watcherBase/
// dirWatchError internals. Each test runs against every watcher available
// on the host OS unless it exercises internal types directly.

package fswatch

import (
	"cmp"
	"errors"
	"fmt"
	"math/rand"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// ----- helpers -----------------------------------------------------------

// defaultEventTimeout is the per-`next` wait used by subscribe tests for
// the fast/responsive backends (inotify, fanotify, Windows). Scales up
// on retry via [watcherEventTimeout] so the fast path is cheap.
func defaultEventTimeout() time.Duration {
	return 1 * time.Second
}

// kqueueFSEventsTimeout is the per-event deadline for the kqueue and
// fsevents backends. Those have materially higher kernel-to-userspace
// latency than inotify/fanotify/Windows: kqueue uses directory
// NOTE_WRITE + compareDir which takes a scheduling round-trip per
// change, and fsevents introduces its own batching on top of the GCD
// dispatch queue. Scales up on retry via [watcherEventTimeout].
func kqueueFSEventsTimeout() time.Duration {
	return 2 * time.Second
}

// watcherEventTimeout returns the appropriate per-event deadline for
// the backend under test, scaled by the current [testingT]'s retry attempt
// number. The fast-path uses the base timeout (1-2 seconds); retries
// scale up so a single environmental hiccup gets a longer wait without
// inflating every passing run's wall-clock.
func watcherEventTimeout(t testingT, w Watcher) time.Duration {
	base := defaultEventTimeout()
	if w == FSEvents() || w == Kqueue() {
		base = kqueueFSEventsTimeout()
	}
	scale := 1
	if rt, ok := t.(*retryT); ok {
		scale = retryTimeoutScale(rt.attempt)
	}
	return base * time.Duration(scale)
}

// availableWatchers is populated at init time from whichever backends
// are available on the current platform, plus any test-only watcher
// variants registered in additionalTestWatchers (see e.g.
// fanotify_linux_test.go).
var availableWatchers []Watcher

// additionalTestWatchers is appended to by platform-specific *_test.go
// init() functions to register test-only watcher variants (e.g. the
// fanotify-no-rename backend that exercises the FAN_MOVED_FROM/_TO
// fallback path). Producers' init() must run before this file's init();
// since Go runs file inits in lexicographic file-name order and this
// file is watcher_test.go, that ordering is satisfied for every other
// *_test.go file in the package.
var additionalTestWatchers []Watcher

func init() {
	for _, b := range AllWatchers() {
		if b.Available() {
			availableWatchers = append(availableWatchers, b)
		}
	}
	for _, b := range additionalTestWatchers {
		if b.Available() {
			availableWatchers = append(availableWatchers, b)
		}
	}
}

// runForEachWatcher runs fn as a subtest for every available watcher.
//
// The per-backend test body receives a [testingT] (a subset of *testing.T)
// rather than the real *testing.T. This lets [runWithRetry] re-run a
// body that fails due to environmental flakes (macOS event-delivery
// stalls under load) before propagating the failure to the real test
// runner.
func runForEachWatcher(t *testing.T, fn func(t testingT, watcherImpl Watcher)) {
	t.Helper()
	for _, b := range availableWatchers {
		t.Run(b.Name(), func(t *testing.T) {
			t.Parallel()
			runWithRetry(t, func(rt testingT) {
				fn(rt, b)
			})
		})
	}
}

// newTmpDir creates a fresh temp dir, resolves any symlinks in the path so
// it matches what backends report, and registers cleanup.
func newTmpDir(t testingT) string {
	t.Helper()
	d := t.TempDir()
	resolved, err := filepath.EvalSymlinks(d)
	if err != nil {
		t.Fatal(err)
	}
	return resolved
}

func makeDirSymlink(t testingT, target string, link string) {
	t.Helper()
	if runtime.GOOS == "windows" {
		if err := exec.Command("cmd", "/c", "mklink", "/J", link, target).Run(); err == nil {
			return
		}
	}
	if err := os.Symlink(target, link); err != nil {
		t.Skipf("directory symlink support is not available: %v", err)
	}
}

// nameCounter generates unique file names per test to avoid collisions.
var nameCounter atomic.Uint64

func uniqueName(parts ...string) string {
	n := nameCounter.Add(1)
	suffix := fmt.Sprintf("test%d%d", n, rand.Int63())
	return filepath.Join(append(parts, suffix)...)
}

// subPath produces a unique name in dir.
func subPath(dir string) string {
	return uniqueName(dir)
}

// newDirectWatcher creates a bare dirWatch for unit-testing tree/debounce
// helpers without going through the full backend subscribe path. Each
// test gets its own debouncer so tests don't share goroutine state.
func newDirectWatcher(t testingT, dir string) *dirWatch {
	t.Helper()
	w := newDirWatch(dir, dir, newDebounce())
	w.recursive = true
	t.Cleanup(func() { w.destroyDebounce() })
	return w
}

// subscribeFor sets up a recorder + WatchDirectory and registers cleanup.
func subscribeFor(t testingT, dir string, watcherImpl Watcher) (*recordingWatcher, Watch) {
	return subscribeForOpts(t, dir, watcherImpl, WithRecursive())
}

// settleSleep is the post-subscribe settle wait. Empirically tuned per
// backend: fsevents and kqueue need a couple of hundred ms to actually
// arm their watches on the freshly-created tmp dir, while inotify/
// fanotify/Windows are essentially synchronous.
func settleSleep(w Watcher) time.Duration {
	if w == FSEvents() || w == Kqueue() {
		return 300 * time.Millisecond
	}
	return 60 * time.Millisecond
}

// preSubscribeSleep gives the macOS fsevents stream timestamp enough
// distance from any tmp-dir creation just before subscribe; without
// it the initial event batch may include the watched dir's own create.
func preSubscribeSleep(w Watcher) time.Duration {
	if w == FSEvents() || w == Kqueue() {
		return 50 * time.Millisecond
	}
	return 0
}

// subscribeFileFor sets up a recorder + WatchFile and registers cleanup.
func subscribeFileFor(t testingT, path string, watcherImpl Watcher) (*recordingWatcher, Watch) {
	t.Helper()
	if d := preSubscribeSleep(watcherImpl); d > 0 {
		time.Sleep(d)
	}
	r := newRecorder(t)
	r.watcher = watcherImpl
	sub, err := watcherImpl.WatchFile(path, r.callback)
	if err != nil {
		t.Fatalf("subscribeFile: %v", err)
	}
	t.Cleanup(func() { _ = sub.Close() })
	time.Sleep(settleSleep(watcherImpl))
	return r, sub
}

// subscribeForOpts sets up a recorder + WatchDirectory with options and registers cleanup.
func subscribeForOpts(t testingT, dir string, watcherImpl Watcher, opts ...WatchOption) (*recordingWatcher, Watch) {
	t.Helper()
	if d := preSubscribeSleep(watcherImpl); d > 0 {
		time.Sleep(d)
	}
	r := newRecorder(t)
	r.watcher = watcherImpl
	sub, err := watcherImpl.WatchDirectory(dir, r.callback, opts...)
	if err != nil {
		t.Fatalf("subscribe: %v", err)
	}
	t.Cleanup(func() { _ = sub.Close() })
	time.Sleep(settleSleep(watcherImpl))
	return r, sub
}

// ----- recordingWatcher --------------------------------------------------

type recordingWatcher struct {
	t       testingT
	watcher Watcher // bound at subscribe time so expect* helpers can choose timeouts
	mu      sync.Mutex
	cond    *sync.Cond
	buf     []Event
	errs    []error
}

func newRecorder(t testingT) *recordingWatcher {
	r := &recordingWatcher{t: t}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// deadline returns the per-event timeout appropriate for the recorder's
// bound watcher backend, or the default if no watcher was attached.
// The returned duration scales with the current retry attempt when the
// recorder is bound to a [retryT].
func (r *recordingWatcher) deadline() time.Duration {
	if r.watcher == nil {
		return scaledDeadline(r.t, defaultEventTimeout())
	}
	return watcherEventTimeout(r.t, r.watcher)
}

// scaledDeadline multiplies base by the retry scale for t (if t is a
// retryT), so per-event timeouts grow on retries without inflating the
// fast path.
func scaledDeadline(t testingT, base time.Duration) time.Duration {
	if rt, ok := t.(*retryT); ok {
		return base * time.Duration(retryTimeoutScale(rt.attempt))
	}
	return base
}

func (r *recordingWatcher) callback(events []Event, err error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err != nil {
		r.errs = append(r.errs, err)
	}
	r.buf = append(r.buf, events...)
	r.cond.Broadcast()
}

// next blocks for up to d for at least one event, then drains and returns
// everything that has accumulated.
func (r *recordingWatcher) next(d time.Duration) []Event {
	r.t.Helper()
	deadline := time.Now().Add(d)
	r.mu.Lock()
	defer r.mu.Unlock()
	for len(r.buf) == 0 {
		remaining := time.Until(deadline)
		if remaining <= 0 {
			return nil
		}
		stopper := time.AfterFunc(remaining, func() {
			r.mu.Lock()
			r.cond.Broadcast()
			r.mu.Unlock()
		})
		r.cond.Wait()
		stopper.Stop()
	}
	out := slices.Clone(r.buf)
	r.buf = nil
	return out
}

// drainQuiet drains any buffered events, then waits at most d to make sure
// no further events arrive. Returns whatever shows up.
func (r *recordingWatcher) drainQuiet(d time.Duration) []Event {
	r.t.Helper()
	r.mu.Lock()
	r.buf = nil
	r.mu.Unlock()
	time.Sleep(d)
	r.mu.Lock()
	out := slices.Clone(r.buf)
	r.buf = nil
	r.mu.Unlock()
	return out
}

// gather waits up to `wait` for at least one event, then settles for
// `settle` to give the rest of the debounced batch a chance to arrive.
func (r *recordingWatcher) gather(wait, settle time.Duration) []Event {
	first := r.next(wait)
	if len(first) == 0 {
		return nil
	}
	time.Sleep(settle)
	r.mu.Lock()
	defer r.mu.Unlock()
	more := slices.Clone(r.buf)
	r.buf = nil
	return append(first, more...)
}

// gatherUntilQuiet collects events until either the initial wait expires
// without seeing one, or the recorder has gone quiet for `quiet`. Useful
// for assertions that need to observe events possibly spread across
// multiple debounce batches (e.g. rapid-coalescing tests).
func (r *recordingWatcher) gatherUntilQuiet(initialWait, quiet time.Duration) []Event {
	first := r.next(initialWait)
	if len(first) == 0 {
		return nil
	}
	all := first
	for {
		more := r.next(quiet)
		if len(more) == 0 {
			return all
		}
		all = append(all, more...)
	}
}

// waitForEvent blocks until an event matching pred is observed in the
// recorder's accumulating buffer, or until deadline elapses. Returns all
// events collected up to the success / timeout (and drains them from the
// buffer). Useful for tests where the kernel backend takes a variable
// amount of time to install/propagate a fresh watch, instead of betting
// on a fixed sleep that breaks under host CPU/IO contention.
func (r *recordingWatcher) waitForEvent(d time.Duration, pred func(Event) bool) []Event {
	r.t.Helper()
	deadline := time.Now().Add(d)
	for {
		r.mu.Lock()
		if slices.ContainsFunc(r.buf, pred) {
			out := slices.Clone(r.buf)
			r.buf = nil
			r.mu.Unlock()
			return out
		}
		remaining := time.Until(deadline)
		if remaining <= 0 {
			out := slices.Clone(r.buf)
			r.buf = nil
			r.mu.Unlock()
			return out
		}
		stopper := time.AfterFunc(remaining, func() {
			r.mu.Lock()
			r.cond.Broadcast()
			r.mu.Unlock()
		})
		r.cond.Wait()
		stopper.Stop()
		r.mu.Unlock()
	}
}

// waitForAll polls the recorder's buffer until every event in want is
// observed (paths matched, kind matched) or d elapses. Returns the full
// accumulated set drained from the buffer either way. Extra events
// outside of want are kept in the returned slice but do not count
// against the deadline.
//
// Use this instead of one-shot r.next() in any test where the kernel
// might split events across multiple debounce batches or take a moment
// to install a watch on a freshly created dir. The retry behavior makes
// the test robust to host CPU/IO contention.
func (r *recordingWatcher) waitForAll(d time.Duration, want []wantEvent) []Event {
	r.t.Helper()
	if len(want) == 0 {
		return nil
	}
	deadline := time.Now().Add(d)
	collected := make([]Event, 0)
	for {
		r.mu.Lock()
		collected = append(collected, r.buf...)
		r.buf = nil
		r.mu.Unlock()
		if haveAll(collected, want) {
			return collected
		}
		remaining := time.Until(deadline)
		if remaining <= 0 {
			return collected
		}
		r.mu.Lock()
		if len(r.buf) > 0 {
			r.mu.Unlock()
			continue
		}
		stopper := time.AfterFunc(remaining, func() {
			r.mu.Lock()
			r.cond.Broadcast()
			r.mu.Unlock()
		})
		r.cond.Wait()
		stopper.Stop()
		r.mu.Unlock()
	}
}

// haveAll reports whether every event in want is matched at least once
// in got. Extra got events are ignored.
func haveAll(got []Event, want []wantEvent) bool {
	for _, w := range want {
		found := false
		for _, e := range got {
			if e.Kind == w.Kind && e.Path == w.Path {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

// expectEventSet polls until every wanted event has arrived (or the
// scaled deadline elapses) and then asserts the matching set
// (ignoring order). Use everywhere the test had next/gather followed
// by assertEventSet; it removes the timing assumption that the events
// land in one debounce batch.
func expectEventSet(t testingT, r *recordingWatcher, want []wantEvent) []Event {
	t.Helper()
	got := r.waitForAll(r.deadline(), want)
	assertEventSet(t, got, want)
	return got
}

// expectEventSequence polls until every wanted event has arrived, then
// asserts they appear in the exact specified order (filtered to
// wanted paths). Order-sensitive callers that previously used
// assertEventSequence on a one-shot next/gather.
func expectEventSequence(t testingT, r *recordingWatcher, want []wantEvent) []Event {
	t.Helper()
	got := r.waitForAll(r.deadline(), want)
	assertEventSequence(t, got, want)
	return got
}

// expectContains polls until any event matching kind+path arrives, then
// returns the accumulated event slice. Use for tests that don't care
// about a specific set of events but want to verify at least one
// specific event surfaced.
func expectContains(t testingT, r *recordingWatcher, kind EventKind, path string) []Event {
	t.Helper()
	d := r.deadline()
	got := r.waitForEvent(d, func(e Event) bool {
		return e.Kind == kind && e.Path == path
	})
	if !containsEvent(got, kind, path) {
		t.Fatalf("expected event %s %s within %s, got %v", kind, path, d, toWantEvents(got))
	}
	return got
}

func expectNoBufferedEvents(t testingT, r *recordingWatcher, msg string) {
	t.Helper()
	r.mu.Lock()
	got := slices.Clone(r.buf)
	r.buf = nil
	r.mu.Unlock()
	if len(got) > 0 {
		t.Fatalf("%s, got %v", msg, toWantEvents(got))
	}
}

func assertNoEventsForPath(t testingT, got []Event, path, msg string) {
	t.Helper()
	got = filterEventsForPaths(got, path)
	if len(got) > 0 {
		t.Fatalf("%s %s, got %v", msg, path, toWantEvents(got))
	}
}

// ----- assertion helpers -------------------------------------------------

type wantEvent struct {
	Kind EventKind
	Path string
}

func toWantEvents(events []Event) []wantEvent {
	out := make([]wantEvent, len(events))
	for i, e := range events {
		out[i] = wantEvent{Kind: e.Kind, Path: e.Path}
	}
	return out
}

// assertEventSet compares two event sets ignoring order.
// Events for paths not in want are ignored (e.g. parent-dir update noise).
func assertEventSet(t testingT, got []Event, want []wantEvent) {
	t.Helper()
	got = filterToWantedPaths(got, want)
	gotW := toWantEvents(got)
	cmpEvents := func(a, b wantEvent) int {
		if a.Kind != b.Kind {
			return cmp.Compare(a.Kind, b.Kind)
		}
		return cmp.Compare(a.Path, b.Path)
	}
	slices.SortFunc(gotW, cmpEvents)
	slices.SortFunc(want, cmpEvents)
	if !equalWantEvents(gotW, want) {
		t.Fatalf("event mismatch\nwant: %v\n got: %v", want, gotW)
	}
}

// assertEventSequence is like assertEventSet but order-sensitive.
// Events for paths not in want are ignored (e.g. parent-dir update noise).
func assertEventSequence(t testingT, got []Event, want []wantEvent) {
	t.Helper()
	got = filterToWantedPaths(got, want)
	gotW := toWantEvents(got)
	if !equalWantEvents(gotW, want) {
		t.Fatalf("event sequence mismatch\nwant: %v\n got: %v", want, gotW)
	}
}

// filterToWantedPaths returns only events whose path appears in want.
func filterToWantedPaths(got []Event, want []wantEvent) []Event {
	paths := make(map[string]struct{}, len(want))
	for _, w := range want {
		paths[w.Path] = struct{}{}
	}
	filtered := make([]Event, 0, len(got))
	for _, e := range got {
		if _, ok := paths[e.Path]; ok {
			filtered = append(filtered, e)
		}
	}
	return filtered
}

func equalWantEvents(a, b []wantEvent) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// containsEvent reports whether got contains an event with the given type+path.
func containsEvent(got []Event, typ EventKind, path string) bool {
	for _, e := range got {
		if e.Kind == typ && e.Path == path {
			return true
		}
	}
	return false
}

func TestPathComparer(t *testing.T) {
	t.Parallel()
	tests := []struct {
		root       string
		path       string
		suffix     string
		exact      bool
		ignoreCase bool
	}{
		{"/root", "/root", "", true, true},
		{"/root", "/root/file.ts", "/file.ts", true, true},
		{"/root", "/ROOT", "", false, true},
		{"/root", "/ROOT/File.ts", "/File.ts", false, true},
		{"/root", "/ROOT/Nested/File.ts", "/Nested/File.ts", false, true},
		{"/root", "/ROOT2/File.ts", "", false, false},
		{"/root", "/roo", "", false, false},
		{"/root/sub", "/ROOT", "", false, false},
		{"/root", "/other/File.ts", "", false, false},
		{"/root", "/ROOTish/File.ts", "", false, false},
		{"/root/sub", "/ROOT/SUB", "", false, true},
		{"/root/sub", "/ROOT/su", "", false, false},
		{"/root/[", "/ROOT/{/File.ts", "", false, false},
		{"/root/@", "/ROOT/`/File.ts", "", false, false},
		{"/", "/File.ts", "File.ts", true, true},
		{"/", "/", "", true, true},
		{"", "", "", false, false},
		{"", "/File.ts", "", false, false},
		{"/caf\u00e9", "/CAF\u00c9/File.ts", "/File.ts", false, true},
		{"/s", "/\u017f/File.ts", "/File.ts", false, true},
		{"/\u017f", "/S/File.ts", "/File.ts", false, true},
		{"/s/sub", "/\u017f/SUB/File.ts", "/File.ts", false, true},
		{"/\u017f/sub", "/S/SUB/File.ts", "/File.ts", false, true},
		{"/s", "/\u017foo/File.ts", "", false, false},
		{"/k", "/\u212a/File.ts", "/File.ts", false, true},
		{"/\u03c3", "/\u03c2/File.ts", "/File.ts", false, true},
		{"/\u00e9", "/\u00c8/File.ts", "", false, false},
		{"/\u00df", "/SS/File.ts", "/File.ts", false, nativePathFolding},
		{"/root/s", "/ROOT/\u017f/File.ts", "/File.ts", false, true},
		{"/root/\u017f", "/ROOT/S", "", false, true},
	}
	for _, tt := range tests {
		for _, ignoreCase := range []bool{false, true} {
			comparer := pathComparer{ignoreCase: ignoreCase}
			want := tt.exact
			if ignoreCase {
				want = tt.ignoreCase
			}
			suffix, ok := comparer.suffix(tt.root, tt.path)
			if ok != want || ok && suffix != tt.suffix {
				t.Errorf("suffix(%q, %q), ignoreCase=%v: got (%q, %v), want (%q, %v)", tt.root, tt.path, ignoreCase, suffix, ok, tt.suffix, want)
			}
			if comparer.contains(tt.root, tt.path) != want {
				t.Errorf("contains(%q, %q), ignoreCase=%v: want %v", tt.root, tt.path, ignoreCase, want)
			}
			for _, to := range []string{"/display", "/"} {
				rebased, ok := comparer.rebase(tt.path, tt.root, to)
				if ok != want || ok && rebased != joinPathSuffix(to, tt.suffix) {
					t.Errorf("rebase(%q, %q, %q), ignoreCase=%v: got (%q, %v)", tt.path, tt.root, to, ignoreCase, rebased, ok)
				}
			}
		}
	}
}

func TestPathComparerUnicodeAlignment(t *testing.T) {
	t.Parallel()
	parts := []string{"s", "S", "\u017f", "k", "K", "\u212a", "\u03c3", "\u03c2", "\u00e9", "\u00c9", "\u00c8", "\U00010400", "\U00010428", "\xff", "\xfe", "\xc3"}
	comparer := pathComparer{ignoreCase: true}
	for padding := range 16 {
		prefix := "/" + strings.Repeat("a", padding)
		for _, a := range parts {
			for _, b := range parts {
				for _, child := range []string{"", "/child"} {
					root := prefix + a + child
					path := prefix + b + strings.ToUpper(child) + "/File.ts"
					want := strings.EqualFold(a, b)
					suffix, ok := comparer.suffix(root, path)
					if ok != want || ok && suffix != "/File.ts" {
						t.Fatalf("suffix(%q, %q): got (%q, %v), want match=%v", root, path, suffix, ok, want)
					}
				}
			}
		}
	}
}

func TestFileCallbackCaseSensitivity(t *testing.T) {
	t.Parallel()
	for _, ignoreCase := range []bool{false, true} {
		var got []Event
		dw := newDirectWatcher(t, "/root")
		dw.setComparer(pathComparer{ignoreCase: ignoreCase})
		dw.addCallback("/root", "/root", false, func(events []Event, err error) {
			got = append(got, events...)
		}, nil, "/root/file.ts")
		dw.events.update("/root/FILE.ts")
		dw.events.update("/root/other.ts")
