func TestDefaultBackendMatchesPlatform(t *testing.T) {
	t.Parallel()
	d := Default()
	var wantName string
	switch runtime.GOOS {
	case "linux":
		if Fanotify().Available() {
			wantName = "fanotify"
		} else {
			wantName = "inotify"
		}
	case "android":
		wantName = "inotify"
	case "darwin":
		wantName = "fsevents"
	case "windows":
		wantName = "windows"
	case "freebsd", "openbsd", "netbsd", "dragonfly":
		wantName = "kqueue"
	default:
		t.Skipf("no expected default watcher for %s", runtime.GOOS)
	}
	if !d.Available() {
		t.Fatalf("Default() should be available on %s", runtime.GOOS)
	}
	if d.Name() != wantName {
		t.Fatalf("Default().Name() = %q, want %q", d.Name(), wantName)
	}
}

